/* Category: Controls, Toggles & Inputs */
(function () {
  var L = (window.MOTION_LAB = window.MOTION_LAB || []);
  L.push(

{ id: 'day-night', title: 'Day / Night Toggle', cat: 'controls', tags: ['toggle', 'css'],
  html: '<label class="dn"><input type="checkbox"><span class="tr"><i class="knob"></i><b class="star s1"></b><b class="star s2"></b><b class="star s3"></b><b class="cloud"></b></span></label>',
  css: '.dn input{position:absolute;opacity:0}\n.tr{position:relative;display:block;width:104px;height:50px;border-radius:99px;background:linear-gradient(#4fb6ff,#1e7fd4);cursor:pointer;overflow:hidden;transition:background .6s;box-shadow:inset 0 2px 8px rgba(0,0,0,.35)}\n.knob{position:absolute;top:5px;left:5px;width:40px;height:40px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#fff3b0,#ffcf3f);box-shadow:0 0 18px rgba(255,207,63,.85);transition:all .55s cubic-bezier(.5,1.6,.4,1)}\n.star{position:absolute;background:#fff;border-radius:50%;opacity:0;transition:opacity .5s}\n.s1{width:4px;height:4px;top:12px;left:20px}\n.s2{width:3px;height:3px;top:30px;left:34px}\n.s3{width:5px;height:5px;top:18px;left:44px}\n.cloud{position:absolute;right:14px;top:16px;width:34px;height:12px;border-radius:99px;background:rgba(255,255,255,.85);box-shadow:-10px -4px 0 -2px rgba(255,255,255,.8);transition:transform .55s,opacity .4s}\n.dn input:checked + .tr{background:linear-gradient(#182a55,#070d22)}\n.dn input:checked + .tr .knob{left:59px;background:radial-gradient(circle at 65% 35%,#e9edf7,#b8c0d6);box-shadow:0 0 18px rgba(220,230,255,.6),inset -6px -3px 0 0 #97a0bb}\n.dn input:checked + .tr .star{opacity:1}\n.dn input:checked + .tr .cloud{transform:translateY(26px);opacity:0}'
},

{ id: 'ios-switch', title: 'Springy Switch', cat: 'controls', tags: ['toggle', 'css'],
  html: '<label class="sw"><input type="checkbox" checked><span></span></label>',
  css: '.sw input{position:absolute;opacity:0}\n.sw span{display:block;width:72px;height:40px;border-radius:99px;background:#3a3a55;cursor:pointer;position:relative;transition:background .35s}\n.sw span::after{content:"";position:absolute;top:4px;left:4px;width:32px;height:32px;border-radius:99px;background:#fff;box-shadow:0 2px 6px rgba(0,0,0,.4);transition:all .4s cubic-bezier(.4,1.8,.4,1)}\n.sw input:checked + span{background:#22c55e}\n.sw input:checked + span::after{left:36px;width:32px}\n.sw span:active::after{width:40px}'
},

{ id: 'check-draw', title: 'Checkbox Tick Draw', cat: 'controls', tags: ['svg', 'toggle'],
  html: '<label class="cd"><input type="checkbox"><span class="bx"><svg viewBox="0 0 24 24"><polyline points="4,13 9,18 20,6"/></svg></span><em>Ship it</em></label>',
  css: '.cd{display:inline-flex;align-items:center;gap:12px;cursor:pointer;color:#e8e8f5;font:600 17px "Space Grotesk",sans-serif}\n.cd input{position:absolute;opacity:0}\n.bx{width:34px;height:34px;border-radius:9px;border:2px solid #6b6b8a;display:grid;place-items:center;transition:all .35s cubic-bezier(.4,1.6,.4,1)}\n.bx svg{width:22px;height:22px;fill:none;stroke:#fff;stroke-width:3;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:26;stroke-dashoffset:26;transition:stroke-dashoffset .4s .1s}\n.cd input:checked + .bx{background:#7c5cff;border-color:#7c5cff;transform:scale(1.1)}\n.cd input:checked + .bx svg{stroke-dashoffset:0}\n.cd input:checked ~ em{color:#7c5cff}\n.cd em{font-style:normal;transition:color .3s}'
},

{ id: 'pill-radio', title: 'Sliding Pill Radio', cat: 'controls', tags: ['js', 'toggle'],
  html: '<div class="pr"><i class="ind"></i><button class="active">Day</button><button>Week</button><button>Month</button></div>',
  css: '.pr{position:relative;display:flex;padding:5px;border-radius:99px;background:rgba(140,140,190,.16);border:1px solid rgba(160,160,210,.2)}\n.pr button{position:relative;z-index:2;padding:9px 20px;border:0;background:transparent;color:#9a9ab0;font:600 14px "Space Grotesk",sans-serif;cursor:pointer;transition:color .3s;border-radius:99px}\n.pr button.active{color:#fff}\n.ind{position:absolute;top:5px;left:5px;height:calc(100% - 10px);border-radius:99px;background:linear-gradient(120deg,#7c5cff,#a855f7);transition:transform .45s cubic-bezier(.4,1.4,.4,1),width .45s cubic-bezier(.4,1.4,.4,1);box-shadow:0 6px 16px -6px #7c5cff}',
  js: 'var w=root.querySelector(".pr"),ind=root.querySelector(".ind"),bs=root.querySelectorAll(".pr button");\nfunction move(b){ind.style.width=b.offsetWidth+"px";ind.style.transform="translateX("+(b.offsetLeft-5)+"px)";}\nbs.forEach(function(b){b.addEventListener("click",function(){bs.forEach(function(x){x.classList.remove("active");});b.classList.add("active");move(b);});});\nsetTimeout(function(){move(bs[0]);},30);'
},

{ id: 'float-label', title: 'Floating Label Field', cat: 'controls', tags: ['input', 'css'],
  html: '<div class="fl"><input id="fl1" type="text" placeholder=" " required><label for="fl1">Email address</label><i class="bar"></i></div>',
  css: '.fl{position:relative;width:230px}\n.fl input{width:100%;padding:18px 14px 8px;border:1px solid rgba(160,160,210,.3);border-radius:10px;background:rgba(140,140,190,.08);color:#e8e8f5;font:400 15px "Space Grotesk",sans-serif;outline:none;transition:border-color .3s}\n.fl label{position:absolute;left:14px;top:15px;color:#9a9ab0;font:400 15px "Space Grotesk",sans-serif;pointer-events:none;transform-origin:left;transition:all .28s cubic-bezier(.4,1.3,.4,1)}\n.fl input:focus{border-color:#7c5cff}\n.fl input:focus + label,.fl input:not(:placeholder-shown) + label{transform:translateY(-10px) scale(.75);color:#7c5cff}\n.bar{position:absolute;left:50%;bottom:0;height:2px;width:0;background:#7c5cff;border-radius:2px;transition:all .35s}\n.fl input:focus ~ .bar{left:0;width:100%}'
},

{ id: 'search-expand', title: 'Expanding Search', cat: 'controls', tags: ['input', 'css'],
  html: '<div class="se"><input type="text" placeholder="Search\u2026"><button><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg></button></div>',
  css: '.se{position:relative;display:flex;align-items:center;justify-content:flex-end;height:50px;width:50px;border-radius:99px;background:rgba(140,140,190,.16);border:1px solid rgba(160,160,210,.25);transition:width .5s cubic-bezier(.65,0,.35,1),background .3s;overflow:hidden}\n.se input{position:absolute;left:0;width:100%;height:100%;padding:0 52px 0 20px;border:0;background:transparent;color:#e8e8f5;font:400 15px "Space Grotesk",sans-serif;outline:none;opacity:0;transition:opacity .3s}\n.se button{position:relative;z-index:2;flex:none;width:50px;height:50px;display:grid;place-items:center;border:0;background:transparent;color:#e8e8f5;cursor:pointer}\n.se button svg{width:21px;height:21px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round}\n.se:hover,.se:focus-within{width:250px;background:rgba(124,92,255,.18)}\n.se:hover input,.se:focus-within input{opacity:1}'
},

{ id: 'range-slider', title: 'Glowing Range Slider', cat: 'controls', tags: ['input', 'js'],
  html: '<div class="rs"><input type="range" min="0" max="100" value="45"><output>45</output></div>',
  css: '.rs{display:grid;gap:14px;justify-items:center;width:240px}\n.rs input{-webkit-appearance:none;appearance:none;width:100%;height:8px;border-radius:99px;background:linear-gradient(90deg,#7c5cff 45%,rgba(140,140,190,.25) 45%);outline:none}\n.rs input::-webkit-slider-thumb{-webkit-appearance:none;width:24px;height:24px;border-radius:50%;background:#fff;border:4px solid #7c5cff;cursor:grab;box-shadow:0 0 0 0 rgba(124,92,255,.45);transition:box-shadow .3s,transform .2s}\n.rs input::-webkit-slider-thumb:hover{transform:scale(1.15);box-shadow:0 0 0 10px rgba(124,92,255,.28)}\n.rs input::-moz-range-thumb{width:20px;height:20px;border-radius:50%;background:#fff;border:4px solid #7c5cff;cursor:grab}\n.rs output{font:700 22px "JetBrains Mono",monospace;color:#7c5cff;font-variant-numeric:tabular-nums}',
  js: 'var r=root.querySelector("input"),o=root.querySelector("output");\nfunction up(){var v=r.value;o.textContent=v;r.style.background="linear-gradient(90deg,#7c5cff "+v+"%,rgba(140,140,190,.25) "+v+"%)";}\nr.addEventListener("input",up);up();'
},

{ id: 'hamburger', title: 'Burger to Cross', cat: 'controls', tags: ['js', 'nav'],
  html: '<button class="bg" aria-label="Menu"><i></i><i></i><i></i></button>',
  css: '.bg{display:grid;gap:7px;padding:16px;border-radius:14px;border:1px solid rgba(160,160,210,.25);background:rgba(140,140,190,.12);cursor:pointer}\n.bg i{display:block;width:34px;height:4px;border-radius:3px;background:#e8e8f5;transition:transform .45s cubic-bezier(.6,0,.3,1.4),opacity .25s,width .35s}\n.bg.on i:nth-child(1){transform:translateY(11px) rotate(45deg);background:#ff5c8a}\n.bg.on i:nth-child(2){opacity:0;width:0}\n.bg.on i:nth-child(3){transform:translateY(-11px) rotate(-45deg);background:#ff5c8a}',
  js: 'var b=root.querySelector(".bg");b.addEventListener("click",function(){b.classList.toggle("on");});'
},

{ id: 'heart-particles', title: 'Heart Burst Particles', cat: 'controls', tags: ['js', 'fun'],
  html: '<button class="hp" aria-pressed="false"><span class="ic">&#9825;</span></button>',
  css: '.hp{position:relative;width:78px;height:78px;border-radius:50%;border:1px solid rgba(160,160,210,.25);background:rgba(140,140,190,.1);cursor:pointer;display:grid;place-items:center}\n.ic{font-size:36px;color:#9a9ab0;transition:transform .35s cubic-bezier(.3,1.7,.4,1),color .3s}\n.hp[aria-pressed="true"] .ic{color:#ff5c8a;transform:scale(1.15)}\n.hp em{position:absolute;top:50%;left:50%;width:7px;height:7px;border-radius:50%;background:#ff5c8a;pointer-events:none;animation:burst .8s ease-out forwards}\n@keyframes burst{0%{transform:translate(-50%,-50%) scale(1)}100%{transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(0);opacity:0}}',
  js: 'var b=root.querySelector(".hp"),ic=b.querySelector(".ic");\nb.addEventListener("click",function(){var on=b.getAttribute("aria-pressed")==="true";b.setAttribute("aria-pressed",String(!on));ic.innerHTML=on?"&#9825;":"&#9829;";if(on)return;for(var i=0;i<12;i++){var e=document.createElement("em"),a=i/12*6.283,d=38+Math.random()*22;e.style.setProperty("--dx",Math.cos(a)*d+"px");e.style.setProperty("--dy",Math.sin(a)*d+"px");b.appendChild(e);}setTimeout(function(){b.querySelectorAll("em").forEach(function(x){x.remove();});},850);});'
},

{ id: 'star-rating', title: 'Star Rating', cat: 'controls', tags: ['css', 'hover'],
  html: '<div class="sr"><i>&#9733;</i><i>&#9733;</i><i>&#9733;</i><i>&#9733;</i><i>&#9733;</i></div>',
  css: '.sr{display:flex;gap:6px;direction:rtl;font-size:34px;line-height:1}\n.sr i{color:#4a4a68;cursor:pointer;transition:transform .25s cubic-bezier(.3,1.7,.4,1),color .2s,text-shadow .3s;font-style:normal}\n.sr i:hover,.sr i:hover ~ i{color:#ffd479;text-shadow:0 0 14px rgba(255,212,121,.8)}\n.sr i:hover{transform:scale(1.3) rotate(-10deg)}'
},

{ id: 'segmented-morph', title: 'Icon Tab Bar', cat: 'controls', tags: ['js', 'nav'],
  html: '<nav class="tb"><button class="on"><svg viewBox="0 0 24 24"><path d="M3 11l9-8 9 8v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/></svg><b>Home</b></button><button><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="M20 20l-4-4"/></svg><b>Search</b></button><button><svg viewBox="0 0 24 24"><path d="M12 21s-7.5-4.7-9.5-9A5.3 5.3 0 0 1 12 6a5.3 5.3 0 0 1 9.5 6c-2 4.3-9.5 9-9.5 9z"/></svg><b>Saved</b></button></nav>',
  css: '.tb{display:flex;gap:6px;padding:8px;border-radius:99px;background:rgba(140,140,190,.14);border:1px solid rgba(160,160,210,.2)}\n.tb button{display:flex;align-items:center;gap:0;padding:11px;border:0;border-radius:99px;background:transparent;color:#9a9ab0;cursor:pointer;overflow:hidden;transition:all .45s cubic-bezier(.5,1.3,.4,1)}\n.tb svg{width:21px;height:21px;flex:none;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.tb b{max-width:0;opacity:0;white-space:nowrap;font:600 14px "Space Grotesk",sans-serif;transition:all .45s cubic-bezier(.5,1.3,.4,1)}\n.tb button.on{background:#7c5cff;color:#fff;padding-right:18px;gap:8px}\n.tb button.on b{max-width:90px;opacity:1}',
  js: 'var bs=root.querySelectorAll(".tb button");bs.forEach(function(b){b.addEventListener("click",function(){bs.forEach(function(x){x.classList.remove("on");});b.classList.add("on");});});'
},

{ id: 'copy-morph', title: 'Copy → Copied', cat: 'controls', tags: ['js', 'state'],
  html: '<button class="cp"><span class="i1"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/></svg>Copy</span><span class="i2"><svg viewBox="0 0 24 24"><polyline points="4,13 9,18 20,6"/></svg>Copied</span></button>',
  css: '.cp{position:relative;width:150px;height:48px;border-radius:12px;border:1px solid rgba(160,160,210,.3);background:rgba(140,140,190,.12);color:#e8e8f5;font:600 14px "Space Grotesk",sans-serif;cursor:pointer;overflow:hidden;transition:background .35s,border-color .35s}\n.cp span{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;gap:8px;transition:transform .45s cubic-bezier(.5,1.4,.4,1),opacity .3s}\n.cp svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.cp .i2{transform:translateY(100%);opacity:0}\n.cp.done{background:rgba(34,197,94,.2);border-color:#22c55e;color:#4ade80}\n.cp.done .i1{transform:translateY(-100%);opacity:0}\n.cp.done .i2{transform:translateY(0);opacity:1}',
  js: 'var b=root.querySelector(".cp");b.addEventListener("click",function(){b.classList.add("done");setTimeout(function(){b.classList.remove("done");},1800);});'
},
{ id: 'password-strength', title: 'Password Meter', cat: 'controls', tags: ['input', 'js'],
  html: '<div class="pw3"><label for="pwi">Password</label><div class="wrap"><input id="pwi" type="text" placeholder="Type something" autocomplete="off" spellcheck="false"><span class="eye">&#9679;&#9679;&#9679;&#9679;&#9679;&#9679;</span></div><div class="mbar"><i></i><i></i><i></i></div><p class="pwmsg">Waiting</p></div>',
  css: '.pw3{display:grid;gap:7px;width:236px}\n.pw3 label{font:600 12px "Space Grotesk",sans-serif;letter-spacing:.06em;color:#9a9ab0;text-transform:uppercase}\n.wrap{position:relative}\n.pw3 input{width:100%;padding:13px 14px;border:1px solid rgba(160,160,210,.3);border-radius:12px;background:rgba(140,140,190,.08);color:#e8e8f5;font:400 15px "Space Grotesk",sans-serif;outline:none;transition:border-color .3s,box-shadow .3s;padding-right:70px}\n.pw3 input:focus{border-color:#7c5cff;box-shadow:0 0 0 4px rgba(124,92,255,.18)}\n.eye{position:absolute;right:13px;top:50%;transform:translateY(-50%);color:#3c3c58;letter-spacing:2px;font-size:13px;pointer-events:none}\n.mbar{display:flex;gap:5px}\n.mbar i{flex:1;height:5px;border-radius:99px;background:rgba(160,160,210,.15);transition:background .35s,box-shadow .35s,transform .3s}\n.pwmsg{margin:0;font:500 12.5px "Space Grotesk",sans-serif;color:#9a9ab0}\n.pw3.l1 .mbar i:nth-child(1){background:#f87171;box-shadow:0 0 10px rgba(248,113,113,.7)}\n.pw3.l2 .mbar i:nth-child(-n+2){background:#fbbf24;box-shadow:0 0 10px rgba(251,191,36,.6)}\n.pw3.l3 .mbar i:nth-child(-n+3){background:#22c55e;box-shadow:0 0 10px rgba(34,197,94,.6)}\n.pw3.l2 .mbar i:nth-child(-n+2),.pw3.l3 .mbar i{transform:scaleY(1.35)}\n.pw3.l1 .pwmsg{color:#f87171}\n.pw3.l2 .pwmsg{color:#fbbf24}\n.pw3.l3 .pwmsg{color:#4ade80}',
  js: 'var inp=root.querySelector("#pwi"),box=root.querySelector(".pw3"),msg=root.querySelector(".pwmsg");\nvar words=["Waiting","Too short","Getting there","Solid","Fortress"];\nfunction rate(v){if(!v.length)return 0;if(v.length<6)return 1;var s=0;if(v.length>=8)s++;if(v.length>=12)s++;var kinds=0;if(/[a-z]/.test(v)&&/[A-Z]/.test(v))kinds++;if(/[0-9]/.test(v))kinds++;if(/[^A-Za-z0-9]/.test(v))kinds++;if(kinds>=1)s++;if(kinds>=2)s++;if(v.length>=16)s++;return Math.min(3,s);}\ninp.addEventListener("input",function(){var l=rate(inp.value);box.className="pw3 l"+l;msg.textContent=words[l];});'
},
{ id: 'pin-code', title: 'PIN Code Input', cat: 'controls', tags: ['input', 'js'],
  html: '<div class="pin3"><div class="pbox"><input maxlength="1" inputmode="numeric" aria-label="Digit 1"><input maxlength="1" inputmode="numeric" aria-label="Digit 2"><input maxlength="1" inputmode="numeric" aria-label="Digit 3"><input maxlength="1" inputmode="numeric" aria-label="Digit 4"></div><p class="pinmsg">Enter your 4-digit code</p></div>',
  css: '.pin3{display:grid;justify-items:center;gap:13px}\n.pbox{display:flex;gap:10px}\n.pbox input{width:48px;height:56px;text-align:center;font:700 22px "JetBrains Mono",monospace;color:#e8e8f5;background:rgba(140,140,190,.09);border:1px solid rgba(160,160,210,.28);border-radius:13px;outline:none;caret-color:#7c5cff;transition:border-color .25s,transform .2s,box-shadow .25s}\n.pbox input:focus{border-color:#7c5cff;transform:translateY(-3px);box-shadow:0 10px 20px -10px rgba(124,92,255,.9)}\n.pbox input.filled{border-color:#22d3ee;color:#22d3ee}\n.pin3.ok .pbox input{border-color:#22c55e;color:#4ade80;animation:pop3 .4s cubic-bezier(.2,1.7,.4,1)}\n.pinmsg{margin:0;font:500 13px "Space Grotesk",sans-serif;color:#9a9ab0;transition:color .3s}\n.pin3.ok .pinmsg{color:#4ade80}\n@keyframes pop3{0%{transform:scale(.72)}100%{transform:scale(1)}}',
  js: 'var box=root.querySelector(".pin3"),ins=root.querySelectorAll(".pbox input"),msg=root.querySelector(".pinmsg");\nfunction check(){var n=0;ins.forEach(function(x){if(x.value)n++;});box.classList.toggle("ok",n===4);msg.innerHTML=n===4?"Unlocked \u2713":"Enter your 4-digit code";}\nins.forEach(function(n,i){n.addEventListener("input",function(){n.value=n.value.replace(/\\D/g,"").slice(0,1);n.classList.toggle("filled",!!n.value);if(n.value&&i<3)ins[i+1].focus();check();});n.addEventListener("keydown",function(e){if(e.key==="Backspace"&&!n.value&&i>0){ins[i-1].focus();ins[i-1].select();}});n.addEventListener("focus",function(){n.select();});});'
},
{ id: 'mini-player', title: 'Mini Music Player', cat: 'controls', tags: ['js', 'media'],
  html: '<div class="pl3 on"><div class="top3"><i class="disc"></i><div class="tt3"><b>Neon Skyline</b><span>The Midnight Drive</span><i class="bars3"><b></b><b></b><b></b></i></div></div><div class="prog3"><i></i><em class="t0">1:24</em><em class="t1">3:41</em></div><div class="ctl3"><button class="sk" data-d="-1" aria-label="Previous track"><svg viewBox="0 0 24 24"><path d="M6 5v14"/><path d="M20 6.5 11 12l9 5.5z" fill="currentColor" stroke="none"/></svg></button><button class="pp" aria-label="Play or pause"><svg class="i-pl" viewBox="0 0 24 24"><path d="M8 5l11 7-11 7z" fill="currentColor" stroke="none"/></svg><svg class="i-pa" viewBox="0 0 24 24"><path d="M7 5v14"/><path d="M17 5v14"/></svg></button><button class="sk" data-d="1" aria-label="Next track"><svg viewBox="0 0 24 24"><path d="M18 5v14"/><path d="M4 6.5 13 12l-9 5.5z" fill="currentColor" stroke="none"/></svg></button></div></div>',
  css: '.pl3{width:240px;padding:14px;border-radius:18px;border:1px solid rgba(160,160,210,.2);background:linear-gradient(150deg,#1b1a33,#10101f);box-shadow:0 20px 40px -22px #000;display:grid;gap:12px}\n.top3{display:flex;align-items:center;gap:13px}\n.disc{position:relative;flex:none;width:62px;height:62px;border-radius:50%;background:repeating-radial-gradient(circle,#191932 0 2px,#23233f 2px 4px);box-shadow:0 0 0 5px #0e0e1d,0 10px 22px -10px #000;animation:sp3 3.6s linear infinite;animation-play-state:paused}\n.disc::after{content:"";position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle at 40% 38%,#7c5cff,#a855f7 65%);-webkit-mask:radial-gradient(circle,#000 0 11px,transparent 12px);mask:radial-gradient(circle,#000 0 11px,transparent 12px)}\n.disc::before{content:"";position:absolute;left:-6px;right:-6px;top:8px;height:16px;background:linear-gradient(rgba(255,255,255,.16),transparent);border-radius:50%;transform:rotate(-24deg);z-index:2}\n.tt3{min-width:0}\n.tt3 b{display:block;font:700 15px "Space Grotesk",sans-serif;color:#ececf5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tt3 span{display:block;font:400 12px;color:#9a9ab0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.bars3{display:flex;align-items:flex-end;gap:2px;height:12px;margin-top:5px}\n.bars3 b{width:3px;background:linear-gradient(#22d3ee,#7c5cff);border-radius:2px;transform:scaleY(.3);transform-origin:bottom;transition:transform .3s}\n.pl3.on .bars3 b{animation:eq3 .9s ease-in-out infinite alternate}\n.bars3 b:nth-child(2){animation-delay:.18s}\n.bars3 b:nth-child(3){animation-delay:.36s}\n.prog3{position:relative;height:18px;display:flex;align-items:center}\n.prog3 i{display:block;height:4px;width:0;border-radius:99px;background:linear-gradient(90deg,#7c5cff,#22d3ee);box-shadow:0 0 8px rgba(124,92,255,.7);position:relative}\n.pl3.on .prog3 i{animation:sweep3 3.6s linear infinite}\n.prog3::before{content:"";position:absolute;inset:7px 0;border-radius:99px;background:rgba(160,160,210,.16)}\n.prog3 i::after{content:"";position:absolute;right:-5px;top:50%;width:11px;height:11px;margin-top:-5.5px;border-radius:50%;background:#fff;border:2px solid #7c5cff}\n.em{position:absolute;font:600 9px "JetBrains Mono",monospace;color:#6d6d8d;font-style:normal;top:1px}\n.t0{left:0}.t1{right:0}\n.ctl3{display:flex;justify-content:center;gap:18px;align-items:center}\n.ctl3 button{display:grid;place-items:center;width:38px;height:38px;border-radius:50%;border:1px solid rgba(160,160,210,.22);background:rgba(140,140,190,.1);color:#e8e8f5;cursor:pointer;transition:all .25s}\n.ctl3 button:hover{border-color:#7c5cff;color:#fff;transform:scale(1.08)}\n.ctl3 svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\n.ctl3 .pp{width:46px;height:46px;background:#7c5cff;border-color:transparent;color:#fff;box-shadow:0 8px 20px -8px #7c5cff}\n.pp .i-pl{display:none}\n.pl3.on .pp .i-pa{display:block}\n.pl3.on .pp .i-pl{display:none}\n.pl3:not(.on) .pp .i-pa{display:none}\n.pl3:not(.on) .pp .i-pl{display:block}\n.pl3.on .disc{animation-play-state:running}\n@keyframes sp3{to{transform:rotate(1turn)}}\n@keyframes eq3{to{transform:scaleY(1)}}\n@keyframes sweep3{from{width:0}to{width:100%}}',
  js: 'var pl=root.querySelector(".pl3"),prog=root.querySelector(".prog3 i");\nfunction kick(){prog.style.animation="none";void prog.offsetWidth;prog.style.animation="";}\npl.querySelector(".pp").addEventListener("click",function(){pl.classList.toggle("on");if(pl.classList.contains("on"))kick();});\npl.querySelectorAll(".sk").forEach(function(b){b.addEventListener("click",function(){kick();var tt=root.querySelector(".tt3 b"),names=["Neon Skyline","Night Arcade","Velvet Static","Chrome Hearts","Neon Skyline"],arts=["The Midnight Drive","Cassette Club","DJ Nova","Velvet Lounge","The Midnight Drive"];var i=Math.floor(Math.random()*4);tt.textContent=names[i];root.querySelector(".tt3 span").textContent=arts[i];});});'
},

{ id: 'radio-tile', title: 'Radio Tiles', cat: 'controls', tags: ['css', 'select'],
  html: '<div class="rt5"><label><input type="radio" name="t5" checked><span>Basic</span></label><label><input type="radio" name="t5"><span>Pro</span></label><label><input type="radio" name="t5"><span>Team</span></label></div>',
  css: '\n.rt5{display:flex;flex-direction:column;gap:8px;width:200px}\n.rt5 label{position:relative;cursor:pointer}\n.rt5 input{position:absolute;opacity:0}\n.rt5 span{display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:1px solid rgba(160,160,210,.2);background:rgba(140,140,190,.05);color:#bdbdda;font:600 13px \'Space Grotesk\',sans-serif;transition:all .25s}\n.rt5 span::before{content:"";width:16px;height:16px;border-radius:50%;border:2px solid rgba(160,160,210,.4);transition:all .25s;flex:none}\n.rt5 input:checked+span{background:rgba(124,92,255,.14);border-color:#7c5cff;color:#fff}\n.rt5 input:checked+span::before{border-color:#22d3ee;background:radial-gradient(circle,#22d3ee 0 40%,transparent 45%)}\n'
}
,

{ id: 'dial-knob', title: 'Dial Knob', cat: 'controls', tags: ['js', 'rotate'],
  html: '<div class="dk5"><div class="k5"><i></i></div><p class="dkl5">Volume <b>50</b></p></div>',
  css: '\n.dk5{display:grid;justify-items:center;gap:10px}\n.k5{position:relative;width:80px;height:80px;border-radius:50%;background:conic-gradient(#7c5cff 0deg,rgba(160,160,210,.18) 0deg 360deg);display:grid;place-items:center;cursor:grab;-webkit-mask:radial-gradient(circle,transparent 34%,#000 35%);mask:radial-gradient(circle,transparent 34%,#000 35%)}\n.k5::before{content:"";width:44px;height:44px;border-radius:50%;background:linear-gradient(145deg,#2a2450,#12101f);box-shadow:inset 0 2px 6px rgba(0,0,0,.6),0 4px 10px rgba(0,0,0,.4)}\n.k5 i{position:absolute;top:8px;width:4px;height:16px;border-radius:3px;background:#22d3ee;box-shadow:0 0 8px #22d3ee;transform-origin:2px 32px}\n.dkl5{margin:0;font:600 12px \'JetBrains Mono\',monospace;color:#9a9ab0}\n.dkl5 b{color:#22d3ee}\n',
  js: 'var k=root.querySelector(\'.k5\'),pos=0,target=0,drag=null,angle=0;var out=root.querySelector(\'.dkl5 b\');function update(){angle=Math.max(0,Math.min(360,angle));var v=Math.round(angle/3.6);out.textContent=v;k.style.background=\'conic-gradient(#7c5cff \'+angle+\'deg,rgba(160,160,210,.18) \'+angle+\'deg 360deg)\';k.querySelector(\'i\').style.transform=\'rotate(\'+angle+\'deg)\';}k.addEventListener(\'pointerdown\',function(e){drag=true;pos=e.clientY;k.setPointerCapture(e.pointerId);});k.addEventListener(\'pointermove\',function(e){if(!drag)return;var dy=pos-e.clientY;pos=e.clientY;angle+=dy*1.4;update();});k.addEventListener(\'pointerup\',function(){drag=false;});api.raf(function(){if(angle%1){};});'
}
,

{ id: 'speed-slider', title: 'Speed Slider', cat: 'controls', tags: ['css', 'range'],
  html: '<div class="sp5"><input type="range" min="0" max="3" step="1" value="1"><div class="ticks5"><span>0</span><span>1</span><span>2</span><span>3</span></div><p>Playback <b>x1</b></p></div>',
  css: '\n.sp5{width:210px;display:grid;gap:6px;justify-items:center}\n.sp5 input{width:100%;appearance:none;height:4px;border-radius:99px;background:linear-gradient(90deg,#7c5cff,#22d3ee);outline:none;cursor:pointer}\n.sp5 input::-webkit-slider-thumb{appearance:none;width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid #7c5cff;box-shadow:0 0 10px rgba(124,92,255,.6);cursor:grab}\n.sp5 input::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid #7c5cff}\n.ticks5{width:100%;display:flex;justify-content:space-between;padding:0 6px;color:#6f6f8c;font:600 10px \'JetBrains Mono\',monospace}\n.sp5 p{margin:0;font:600 12px \'Space Grotesk\',sans-serif;color:#9a9ab0}\n.sp5 p b{color:#22d3ee;font:600 13px \'JetBrains Mono\',monospace}\n',
  js: 'var inp=root.querySelector(\'input\'),lab=root.querySelector(\'b\');function up(){var t={0:\'Pause\',1:\'x1\',2:\'x2\',3:\'x4\'}[+inp.value];lab.textContent=t;}inp.addEventListener(\'input\',up);up();'
}
,

{ id: 'theme-preview', title: 'Theme Picker', cat: 'controls', tags: ['js', 'theme'],
  html: '<div class="th5"><button data-c="#ff5c8a,#ff9d5c">Sunset</button><button data-c="#22d3ee,#7c5cff">Ocean</button><button data-c="#4ade80,#a3e635">Mint</button><p>Pick a vibe</p></div>',
  css: '\n.th5{width:210px;display:grid;gap:10px;justify-items:center}\n.th5 button{width:100%;display:flex;align-items:center;gap:8px;padding:9px 12px;border:0;border-radius:9px;background:rgba(140,140,190,.08);color:#cfcfe6;font:600 13px \'Space Grotesk\',sans-serif;cursor:pointer;transition:all .25s}\n.th5 button::before{content:"";width:18px;height:18px;border-radius:50%;background:linear-gradient(135deg,var(--a),var(--b))}\n.th5 button:hover{transform:translateX(4px)}\n.th5 button.on{background:rgba(140,140,190,.2);color:#fff}\n.th5 p{margin:0;font:600 12px \'JetBrains Mono\',monospace;color:#8f8fa8}\n',
  js: 'var btns=root.querySelectorAll(\'button\'),preview=root.querySelector(\'.th5\');btns.forEach(function(b){var c=b.dataset.c.split(\',\');b.style.setProperty(\'--a\',c[0]);b.style.setProperty(\'--b\',c[1]);b.addEventListener(\'click\',function(){btns.forEach(function(x){x.classList.remove(\'on\');});b.classList.add(\'on\');preview.style.background=\'linear-gradient(120deg,\'+c[0]+\',\'+c[1]+\')\';preview.style.boxShadow=\'0 0 30px rgba(0,0,0,.4)\';});});'
}
,

{ id: 'switch-labels', title: 'Labeled Switch', cat: 'controls', tags: ['css', 'toggle'],
  html: '<label class="ls5"><input type="checkbox"><span class="tr5"></span><em>Night mode</em></label>',
  css: '\n.ls5{display:flex;align-items:center;gap:12px;cursor:pointer;font:600 14px \'Space Grotesk\',sans-serif;color:#d3d3ea}\n.ls5 input{display:none}\n.tr5{position:relative;width:48px;height:26px;border-radius:99px;background:rgba(140,140,190,.25);transition:background .3s;flex:none}\n.tr5::after{content:"";position:absolute;top:3px;left:3px;width:20px;height:20px;border-radius:50%;background:#fff;transition:transform .3s cubic-bezier(.3,1.3,.4,1);box-shadow:0 2px 6px rgba(0,0,0,.4)}\n.ls5 input:checked+.tr5{background:linear-gradient(90deg,#7c5cff,#22d3ee)}\n.ls5 input:checked+.tr5::after{transform:translateX(22px)}\n.ls5 input:checked~em{color:#fff}\n'
}
,

{ id: 'range-bars', title: 'Bar Range', cat: 'controls', tags: ['js', 'range'],
  html: '<div class="vb5"><div class="bars5"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><input type="range" min="0" max="8" value="5"></div>',
  css: '\n.vb5{width:200px;display:grid;gap:14px;justify-items:center}\n.bars5{display:flex;align-items:flex-end;gap:5px;height:64px}\n.bars5 i{width:12px;border-radius:4px;background:#7c5cff;transition:height .2s;height:6px}\n.bars5 i:nth-child(2n){background:#22d3ee}\n.vb5 input{width:100%;appearance:none;height:5px;border-radius:99px;background:rgba(140,140,190,.25);outline:none}\n.vb5 input::-webkit-slider-thumb{appearance:none;width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid #22d3ee;cursor:pointer}\n.vb5 input::-moz-range-thumb{width:18px;height:18px;border-radius:50%;background:#fff;border:3px solid #22d3ee}\n',
  js: 'var inp=root.querySelector(\'input\'),bars=root.querySelectorAll(\'.bars5 i\');function up(){for(var i=0;i<8;i++){var on=i<+inp.value;bars[i].style.height=(on? (12+Math.pow(i+1,1.6)*4):8)+\'px\';bars[i].style.opacity=on?\'1\':\'.25\';}}inp.addEventListener(\'input\',up);up();'
}
,

{ id: 'dot-indicator', title: 'Dot Indicator', cat: 'controls', tags: ['js', 'pagination'],
  html: '<div class="di5"><div class="dots5"><button></button><button class="on"></button><button></button><button></button><button></button></div><p>Slide 2 / 5</p></div>',
  css: '\n.di5{display:grid;justify-items:center;gap:12px}\n.dots5{display:flex;gap:10px;align-items:center}\n.dots5 button{width:10px;height:10px;border:0;padding:0;border-radius:50%;background:rgba(140,140,190,.35);cursor:pointer;transition:all .35s cubic-bezier(.3,1.4,.4,1)}\n.dots5 button.on{width:30px;border-radius:99px;background:linear-gradient(90deg,#7c5cff,#22d3ee);transform:scaleY(1.2)}\n.di5 p{margin:0;font:600 12px \'JetBrains Mono\',monospace;color:#8f8fa8}\n',
  js: 'var btns=root.querySelectorAll(\'.dots5 button\'),out=root.querySelector(\'p\'),cur=1;btns.forEach(function(b,i){b.addEventListener(\'click\',function(){cur=i+1;render();});});function render(){btns.forEach(function(b,i){b.classList.toggle(\'on\',i===cur-1);});out.textContent=\'Slide \'+cur+\' / \'+btns.length;}setInterval(function(){cur=cur%btns.length+1;render();},2200);'
}

  );
})();
